    dict(id='m-reinforce-review', role='mentor', group='Reinforcement', title='Reinforcement: read the results and decide next steps', summary='Student overview, chapter matrix, patterns and recommendations.',
         where=[('Students', 'reinforce.mentor_home')],
         steps=['Students shows each student with their status (overdue, pending, nothing pending), answers given, accuracy, trend and chapters needing attention. Filter by exam, group or status.',
                'Open a student to see the chapter-wise table. A chapter is judged only after enough different questions have been answered; until then it reads "Insufficient data".',
                'Click a chapter to drill down to topics and individual answers with the confidence given.',
                'The four patterns: correct and High = secure; correct but Guess/Low = may be lucky or unsure; wrong and Guess/Low = a gap the student knows about; wrong and High = a possible misconception.',
                'Press "Generate suggestions" to get rule-based recommendations. Approve and assign, Modify (opens the builder filled in) or Reject. Nothing is assigned without your approval.',
                'Add an observation or follow-up date; tick "Include in the parent report" to share a note with the parent.'],
         tips=['Thresholds (minimum questions, accuracy cut-offs) are set by the admin under Reinforcement > Admin.'],
         added='2026-10-26', updated='2026-10-26'),
